// Follow-ups are automated template messages - send 24/7 (no business hours restriction)
// Business hours only apply to human handover, not automated follow-ups
const now = new Date().toISOString();
return [{ json: { now, isBusinessHours: true } }];

// Prepare WhatsApp template message for follow-up
const lead = $input.first().json;
let phone = lead.phone_number.replace(/[^0-9]/g, '');
if (/^0\d{9}$/.test(phone)) phone = '27' + phone.slice(1);
const name = lead.full_name || 'there';

// ew_followup_nudge body: "Hi {{1}}, we're still keeping an eye on {{2}} for you..."
// {{2}} is the garment — offered_package holds the recommended item, falling
// back to product_interest. Field names are legacy telecoms labels.
const pkg = lead.offered_package || lead.product_interest || 'the item you were looking at';

return {
  json: {
    leadId: lead.id,
    phone: phone,
    templateName: 'ew_followup_nudge',
    name: name,
    pkg: pkg
  }
};

const sendResult = $input.first().json;
const prepData = $('Prepare Follow-up Message').first().json;
const errorTime = new Date().toISOString();

// Extract error details from Meta API response
let errorMessage = 'Unknown error';
let errorCode = '';
if (sendResult.error) {
  errorMessage = sendResult.error.message || JSON.stringify(sendResult.error);
  errorCode = sendResult.error.code || '';
} else if (sendResult.message && sendResult.httpCode) {
  errorMessage = sendResult.message;
  errorCode = sendResult.httpCode;
}

const leadName = prepData.name || 'Unknown';
const leadPhone = prepData.phone || 'Unknown';
const templateName = prepData.templateName || 'ew_followup_nudge';

const htmlContent = `<div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto;">
  <div style="background: #dc3545; padding: 20px; border-radius: 10px 10px 0 0; text-align: center;">
    <h1 style="color: white; margin: 0;">⚠️ WhatsApp Template Send Failed</h1>
    <p style="color: white; margin: 5px 0 0 0;">Follow-up reminder could not be delivered</p>
  </div>
  <div style="padding: 20px; border: 1px solid #ddd; border-top: none; border-radius: 0 0 10px 10px;">
    <h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px;">Error Details</h2>
    <table style="width: 100%; border-collapse: collapse;">
      <tr><td style="padding: 8px; font-weight: bold; width: 180px;">Workflow:</td><td style="padding: 8px;">Layla Follow-up Sender</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Template:</td><td style="padding: 8px;">${templateName}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Lead Name:</td><td style="padding: 8px;">${leadName}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Lead Phone:</td><td style="padding: 8px;">${leadPhone}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Error Code:</td><td style="padding: 8px; color: #dc3545; font-weight: bold;">${errorCode}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Error Message:</td><td style="padding: 8px;">${errorMessage}</td></tr>
      <tr><td style="padding: 8px; font-weight: bold;">Time:</td><td style="padding: 8px;">${errorTime}</td></tr>
    </table>
    <h2 style="color: #333; border-bottom: 2px solid #dc3545; padding-bottom: 10px; margin-top: 20px;">Action Required</h2>
    <ul style="padding-left: 20px;">
      <li style="padding: 5px 0;">Check the template configuration in Meta Business Manager</li>
      <li style="padding: 5px 0;">Verify template parameters match the expected count</li>
      <li style="padding: 5px 0;">Check the n8n workflow: <a href="https://n8n.horizonafrica.co.za/workflow/6910G5ugptqI0pHC">Open in n8n</a></li>
      <li style="padding: 5px 0;">The lead has NOT been marked as sent and will be retried on the next run</li>
    </ul>
    <hr style="margin-top: 20px; border: none; border-top: 1px solid #ddd;">
    <p style="color: #999; font-size: 12px; text-align: center;">This alert was generated by the Layla Follow-up Sender workflow</p>
  </div>
</div>`;

return { json: {
  sender: { name: 'Eastern Wear by Kersh', email: 'keshlan@horizonafrica.co.za' },
  to: [{ email: 'sifosman@gmail.com', name: 'Sif' }],
  subject: '⚠️ WhatsApp Template Send Failed: ' + templateName + ' to ' + leadName,
  htmlContent: htmlContent
} };
